#include "core.h"

// FM+STAT: generated by tools/make_engine.py. The sound is in voices/fmp.hpp.
namespace mmstat {
inline void initialize(Voice& voice, Shared& shared, u32 owner) { md::fmpstat::reset(voice.state, shared.common, owner); }
inline void start(Voice& voice, Shared& shared, u32) { md::fmpstat::trigger(voice.state, shared.common); }
inline void destroy(Voice&, Shared&, u32) {}
inline void render(Voice& voice, Shared& shared, u32, opxy::Output output, opxy::Parameters parameters, opxy::Pitch pitch) {
    md::fmpstat::render(voice.state, shared.common, output, parameters, pitch);
}
}
